#pragma once
#include "compiled/ControlGraph.hpp"
#include "api/EngineTypes.hpp"
#include <array>
#include <cstddef>
#include <cstdint>
#include <limits>

namespace player2 {
// Bounded outcomes of Actions inside external Event / Entry inputs, not another
// executor. Nested Events replay their successful children, but a rejected leaf
// must not become successful after an asset is bound or a page becomes warm.
// Scope ranges belong to CommandJournal records. Compiled timeline Actions are
// still regenerated by the same EngineRuntime and its preparation history.
class ActionDecisionJournal {
public:
    static constexpr std::uint32_t capacity=32768;
    static constexpr std::uint32_t absent=std::numeric_limits<std::uint32_t>::max();
    struct Record { ActionKind kind{}; int target{-1}; api::EngineStatus result{}; std::uint32_t end{}; };
    struct Token { std::uint32_t index{absent}; bool replay{},invalid{}; };
private:
    std::array<Record,capacity> records_{};
    std::uint32_t size_{},cursor_{},limit_{};
    bool active_{},replay_{},complete_{true};
public:
    bool complete()const noexcept{return complete_;}
    std::uint32_t cursor()const noexcept{return cursor_;}
    void rewind()noexcept{cursor_=0;active_=replay_=false;}
    void branch(bool recordActions)noexcept{size_=cursor_;active_=recordActions;replay_=false;}
    bool replay(std::uint32_t begin,std::uint32_t end,bool recordActions)noexcept {
        active_=recordActions;replay_=true;limit_=end;
        if(begin!=cursor_ || begin>end || end>size_){complete_=false;return false;}
        return true;
    }
    void endScope()noexcept {
        if(replay_ && cursor_!=limit_)complete_=false;
        active_=replay_=false;
    }
    Token enter(ActionKind kind,int target)noexcept {
        if(!active_)return {};
        if(replay_) {
            if(cursor_>=limit_ || cursor_>=size_ || records_[cursor_].kind!=kind || records_[cursor_].target!=target) {
                complete_=false;return {absent,true,true};
            }
            return {cursor_++,true,false};
        }
        if(cursor_==capacity){complete_=false;return {};}
        const auto index=cursor_++;size_=cursor_;
        records_[index]={kind,target,api::EngineStatus::Ok,cursor_};
        return {index,false,false};
    }
    bool rejectedLeaf(Token token)const noexcept {
        return token.replay && !token.invalid && token.index!=absent &&
            records_[token.index].kind!=ActionKind::Event && records_[token.index].result!=api::EngineStatus::Ok;
    }
    api::EngineStatus result(Token token)const noexcept{return records_[token.index].result;}
    void finish(Token token,api::EngineStatus& result)noexcept {
        if(token.index==absent)return;
        auto& record=records_[token.index];
        if(token.replay) {
            if(cursor_!=record.end){complete_=false;result=api::EngineStatus::ResourceLimit;}
            else result=record.result;
        } else {record.result=result;record.end=cursor_;}
    }
};
static_assert(sizeof(ActionDecisionJournal)<1024*1024,"Action replay storage must remain bounded below 1 MiB");
}
